property.value:
//MethodCall[
  (@MethodName = 'equals' or @MethodName = 'equalsIgnoreCase')
  and ArgumentList/*[
    self::StringLiteral or self::InfixExpression[descendant::StringLiteral]
  ]
  and (pmd-java:matchesSig('java.lang.String#equals(java.lang.Object)')
       or pmd-java:matchesSig('java.lang.String#equalsIgnoreCase(java.lang.String)'))
]

//InfixExpression[
  (
    @Operator = '||'
    and MethodCall[
      pmd-java:matchesSig('java.lang.String#isEmpty()')
    ]/VariableAccess/@Name
      = InfixExpression[@Operator = '==' and NullLiteral]/VariableAccess/@Name
  ) or (
    @Operator = '&&'
    and UnaryExpression[@Operator = '!']/MethodCall[
      pmd-java:matchesSig('java.lang.String#isEmpty()')
    ]/VariableAccess/@Name
      = InfixExpression[@Operator = '!=' and NullLiteral]/VariableAccess/@Name
  )
]

//InfixExpression[
  (
    (@Operator = ('==', '!=', '>', '<='))
    and MethodCall[
      pmd-java:matchesSig('com.fasterxml.jackson.databind.JsonNode#size()')
    ]
    and NumericLiteral[@ValueAsInt = 0]
  ) or (
    (@Operator = ('==', '!=', '<', '>='))
    and NumericLiteral[@ValueAsInt = 0]
      [following-sibling::MethodCall[
        pmd-java:matchesSig('com.fasterxml.jackson.databind.JsonNode#size()')
      ]]
  )
]

//InfixExpression[
  (
    @Operator = ('==', '!=', '>', '<=')
    and MethodCall[
      @MethodName = 'length'
      and *[1][
        pmd-java:typeIs('java.lang.CharSequence')
        or pmd-java:typeIs('java.lang.String')
        or pmd-java:typeIs('java.lang.StringBuilder')
        or pmd-java:typeIs('java.lang.StringBuffer')
      ]
      and following-sibling::NumericLiteral[@ValueAsInt = 0]
    ]
  ) or (
    @Operator = ('==', '!=', '<', '>=')
    and NumericLiteral[@ValueAsInt = 0]
      [following-sibling::MethodCall[
        @MethodName = 'length'
        and *[1][
          pmd-java:typeIs('java.lang.CharSequence')
          or pmd-java:typeIs('java.lang.String')
          or pmd-java:typeIs('java.lang.StringBuilder')
          or pmd-java:typeIs('java.lang.StringBuffer')
        ]
      ]]
  )
]

//LambdaExpression[
  LambdaParameterList[count(LambdaParameter) = 1]
  and MethodCall[
    TypeExpression
    and ArgumentList[count(*) = 1]
    and ArgumentList/VariableAccess/@Name
        = ancestor::LambdaExpression[1]/LambdaParameterList/LambdaParameter/VariableId/@Name
  ]
]
